package com.android.tools.lint.checks;

import static com.android.SdkConstants.*;

import com.android.SdkConstants;
import com.android.annotations.NonNull;
import com.android.ide.common.resources.configuration.FolderConfiguration;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.*;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

import java.io.File;
import java.util.*;

public class ArraySizeDetector extends ResourceFolderDetector {
    private Map<String, List<ArrayData>> mArrays;

    private static final String ARRAY = "array";
    private static final String STRING_ARRAY = "string-array";
    private static final String INTEGER_ARRAY = "integer-array";

    private static final String[] ARRAY_TYPES = new String[] { ARRAY, STRING_ARRAY, INTEGER_ARRAY };

    public static final Issue ISSUE = Issue.create(
        "InconsistentArrays",
        "Inconsistent number of elements in arrays",
        "When an array is translated in a different locale, it should normally have the same number of elements as the original array...",
        Category.MESSAGES,
        5,
        Severity.WARNING,
        new Implementation(ArraySizeDetector.class, Scope.RESOURCE_FOLDER_SCOPE)
    );

    @Override
    public void beforeCheckProject(@NonNull Context context) {
        mArrays = new HashMap<>();
    }

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.VALUES;
    }

    @Override
    public void checkFolder(@NonNull ResourceFolderContext context, @NonNull File folder) {
        File[] files = folder.listFiles();
        if (files == null) return;
        for (File file : files) {
            if (file.isFile() && file.getName().endsWith(DOT_XML)) {
                checkFile(context, file);
            }
        }
    }

    private void checkFile(Context context, File file) {
        Document document = XmlUtils.parseDocumentSilently(file, true);
        if (document == null) return;
        Element root = document.getDocumentElement();
        if (root == null || !TAG_RESOURCES.equals(root.getTagName())) return;
        NodeList children = root.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node node = children.item(i);
            if (node.getNodeType() == Node.ELEMENT_NODE) {
                Element element = (Element) node;
                String tag = element.getTagName();
                if (isArray(tag)) {
                    String name = element.getAttribute(ATTR_NAME);
                    if (name != null && !name.isEmpty()) {
                        int count = getChildCount(element);
                        String array = tag + "/" + name; // maybe just name
                        List<ArrayData> list = mArrays.get(array);
                        if (list == null) {
                            list = new ArrayList<>();
                            mArrays.put(array, list);
                        }
                        list.add(new ArrayData(name, count, file, context));
                    }
                }
            }
        }
    }

    private boolean isArray(String tag) {
        return tag.equals(TAG_ARRAY) || tag.equals(TAG_STRING_ARRAY) || tag.equals(TAG_INTEGER_ARRAY);
    }

    private int getChildCount(Element element) {
        int count = 0;
        NodeList children = element.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node node = children.item(i);
            if (node.getNodeType() == Node.ELEMENT_NODE && TAG_ITEM.equals(((Element)node).getTagName())) {
                count++;
            }
        }
        return count;
    }

    @Override
    public void afterCheckProject(@NonNull Context context) {
        for (Map.Entry<String, List<ArrayData>> entry : mArrays.entrySet()) {
            List<ArrayData> list = entry.getValue();
            if (list.size() <= 1) continue;
            int expected = list.get(0).count;
            boolean same = true;
            for (ArrayData data : list) {
                if (data.count != expected) {
                    same = false;
                    break;
                }
            }
            if (!same) {
                // report on each file with different count
                for (ArrayData data : list) {
                    if (data.count != expected) {
                        context.report(ISSUE, data.location, String.format("Array ... has %d items, expected %d", data.count, expected));
                    }
                }
            }
        }
    }

    private static class ArrayData {
        final String name;
        final int count;
        final File file;
        final Location location;
        ArrayData(String name, int count, File file, Context context) {
            this.name = name;
            this.count = count;
            this.file = file;
            this.location = context.getRangeLocation(file, 0, 0, 0); // maybe
        }
    }
}

