package com.android.tools.lint.checks;

import static com.android.SdkConstants.ATTR_NAME;
import static com.android.SdkConstants.TAG_ARRAY;
import static com.android.SdkConstants.TAG_INTEGER_ARRAY;
import static com.android.SdkConstants.TAG_ITEM;
import static com.android.SdkConstants.TAG_STRING_ARRAY;

import com.android.annotations.NonNull;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.Category;
import com.android.tools.lint.detector.api.Context;
import com.android.tools.lint.detector.api.Detector;
import com.android.tools.lint.detector.api.Implementation;
import com.android.tools.lint.detector.api.Issue;
import com.android.tools.lint.detector.api.Location;
import com.android.tools.lint.detector.api.Scope;
import com.android.tools.lint.detector.api.Severity;
import com.android.tools.lint.detector.api.XmlContext;
import com.google.common.collect.Maps;

import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Map;

public class ArraySizeDetector extends Detector implements Detector.XmlScanner {

    private Map<String, List<ArrayEntry>> mArrays;

    private static class ArrayEntry {
        final String name;
        final String folder;
        final int size;
        final Location location;

        ArrayEntry(String name, String folder, int size, Location location) {
            this.name = name;
            this.folder = folder;
            this.size = size;
            this.location = location;
        }
    }

    @Override
    public void beforeCheckEachProject(@NonNull Context context) {
        mArrays = Maps.newHashMap();
    }

    @Override
    public boolean appliesTo(@NonNull ResourceFolderType folderType) {
        return folderType == ResourceFolderType.VALUES;
    }

    @Override
    @NonNull
    public Collection<String> getApplicableElements() {
        return Arrays.asList(TAG_ARRAY, TAG_STRING_ARRAY, TAG_INTEGER_ARRAY);
    }

    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        String name = element.getAttribute(ATTR_NAME);
        if (name == null || name.isEmpty()) {
            return;
        }

        int count = 0;
        NodeList childNodes = element.getChildNodes();
        for (int i = 0, n = childNodes.getLength(); i < n; i++) {
            Node child = childNodes.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE && TAG_ITEM.equals(child.getNodeName())) {
                count++;
            }
        }

        String folder = context.file.getParentFile().getName();
        String key = name + "/" + element.getTagName();
        List<ArrayEntry> entries = mArrays.get(key);
        if (entries == null) {
            entries = new ArrayList<>();
            mArrays.put(key, entries);
        }
        entries.add(new ArrayEntry(name, folder, count, context.getElementLocation(element)));
    }

    @Override
    public void afterCheckEachProject(@NonNull Context context) {
        for (List<ArrayEntry> entries : mArrays.values()) {
            if (entries.size() < 2) {
                continue;
            }

            ArrayEntry base = null;
            for (ArrayEntry entry : entries) {
                if ("values".equals(entry.folder)) {
                    base = entry;
                    break;
                }
            }
            if (base == null) {
                base = entries.get(0);
            }

            for (ArrayEntry entry : entries) {
                if (entry.size != base.size) {
                    String message = String.format(
                            "Array %1$s has %2$d items in %3$s, expected %4$d (%5$s)",
                            entry.name, entry.size, entry.folder, base.size, base.folder);
                    context.report(ISSUE, entry.location, message);
                }
            }
        }
    }

    public static final Issue ISSUE = Issue.create(
            "InconsistentArrays",
            "Inconsistent number of elements in arrays",
            "When an array is translated in a different locale, it should normally have "
                    + "the same number of elements as the original array. ...",
            Category.MESSAGES,
            5,
            Severity.WARNING,
            new Implementation(ArraySizeDetector.class, Scope.RESOURCE_FILE_SCOPE)
    );
}
```

