                String message = String.format(
                        "Array '%1$s' has %2$d items in %3$s, expected %4$d (%5$s)",
                        baseline.name, baseline.count, baseline.folder, other.count, other.folder);
                context.report(ISSUE, baseline.location, message);
            }
        }
    }

    private static class ArrayEntry {
        final String name;
        final String tag;
        final String folder;
        final File file;
        int count;
        Location location;

        ArrayEntry(String name, String tag, String folder, int count, Location location, File file) {
            this.name = name;
            this.tag = tag;
            this.folder = folder;
            this.count = count;
            this.location = location;
            this.file = file;
        }
